selector_to_html = {"a[href=\"#asr\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Automatic Speech Recognition (ASR) (coming soon)<a class=\"headerlink\" href=\"#asr\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"../../example/Python.html#py-get-mic-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.22 </span>Get Current Microphone Source<a class=\"headerlink\" href=\"#py-get-mic-source\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#def-rosmsg-audiodata\"]": "<ul id=\"def-rosmsg-audiodata\">\n<li><p>AudioData ros2-msg @ hal/audio/msg/AudioData.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">uint8</span><span class=\"o\">[]</span><span class=\"w\"> </span><span class=\"n\">data</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"#def-rossrv-getmute\"]": "<ul id=\"def-rossrv-getmute\">\n<li><p><code class=\"docutils literal notranslate\"><span class=\"pre\">GetMute</span></code> ros2-srv @ /hal/audio/srv/GetMute.srv</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Get Mute Status</span>\n<span class=\"c1\"># Service: /aimdk_5Fmsgs/srv/GetMute</span>\n\n<span class=\"c1\"># Request</span>\n<span class=\"n\">CommonRequest</span><span class=\"w\"> </span><span class=\"n\">request</span><span class=\"w\">            </span><span class=\"c1\"># Request header</span>\n\n<span class=\"o\">---</span>\n\n<span class=\"c1\"># Response</span>\n<span class=\"n\">CommonResponse</span><span class=\"w\"> </span><span class=\"n\">reponse</span><span class=\"w\">           </span><span class=\"c1\"># Response header</span>\n<span class=\"n\">bool</span><span class=\"w\"> </span><span class=\"n\">is_mute</span><span class=\"w\">                     </span><span class=\"c1\"># Current mute state</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"#audio-playback-raw\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Audio Stream Playback<a class=\"headerlink\" href=\"#audio-playback-raw\" title=\"Link to this heading\">\uf0c1</a></h2><p>Provides raw audio stream playback support</p>", "a[href=\"../../example/Cpp.html#cpp-mic-raw-receiver\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.21 </span>Raw Microphone Audio Stream Receiver<a class=\"headerlink\" href=\"#cpp-mic-raw-receiver\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses mic_raw_receiver</strong>, which subscribes to the <code class=\"docutils literal notranslate\"><span class=\"pre\">/aima/hal/audio/capture</span></code> topic to receive raw audio data from the robot and automatically saves it to PCM files split by channel.</p><p><strong>Features:</strong></p>", "a[href=\"#id10\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Programming Examples<a class=\"headerlink\" href=\"#id10\" title=\"Link to this heading\">\uf0c1</a></h2><p>For detailed programming examples and code descriptions, see:</p>", "a[href=\"#def-rossrv-requestaudiofocus\"]": "<ul id=\"def-rossrv-requestaudiofocus\">\n<li><p>RequestAudioFocus ros2-srv @ hal/audio/srv/RequestAudioFocus.srv</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Request audio playback focus</span>\n<span class=\"c1\"># Service: /aimdk_5Fmsgs/srv/RequestAudioFocus</span>\n\n<span class=\"c1\"># Request</span>\n<span class=\"n\">CommonRequest</span><span class=\"w\"> </span><span class=\"n\">request</span><span class=\"w\"> </span><span class=\"c1\"># Request header</span>\n\n<span class=\"n\">FocusRequester</span><span class=\"w\"> </span><span class=\"n\">focus_requester</span><span class=\"w\"> </span><span class=\"c1\"># Focus request info</span>\n\n<span class=\"o\">---</span>\n\n<span class=\"c1\"># Response</span>\n<span class=\"n\">CommonResponse</span><span class=\"w\"> </span><span class=\"n\">reponse</span><span class=\"w\"> </span><span class=\"c1\"># Response header</span>\n\n<span class=\"n\">FocusResponse</span><span class=\"w\"> </span><span class=\"n\">focus_response</span><span class=\"w\"> </span><span class=\"c1\"># Request result</span>\n</pre></div>\n</div>\n<ul id=\"def-rosmsg-focusrequester\">\n<li><p>FocusRequester ros2-msg @ hal/audio/msg/FocusRequester.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Playback source identifier</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">priority</span><span class=\"w\"> </span><span class=\"c1\"># Priority (1\u201310, default 6)</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">priority_weight</span><span class=\"w\"> </span><span class=\"c1\"># Weight (optional); breaks ties within same priority level</span>\n</pre></div>\n</div>\n</li>\n</ul>\n<ul id=\"def-rosmsg-focusresponse-common\">\n<li><p>FocusResponse ros2-msg @ hal/audio/msg/FocusResponse.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Playback source identifier</span>\n\n<span class=\"n\">bool</span><span class=\"w\"> </span><span class=\"n\">focus_gain</span><span class=\"w\"> </span><span class=\"c1\"># Focus grant result</span>\n</pre></div>\n</div>\n</li>\n</ul>\n</li>\n</ul>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Key Features<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">\uf0c1</a></h2><h3>Text-to-Speech (TTS)<a class=\"headerlink\" href=\"#tts\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"#def-rosmsg-vad\"]": "<ul id=\"def-rosmsg-vad\">\n<li><p><code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessedAudioOutput</span></code> ros2-msg @ interaction/msg/ProcessedAudioOutput.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">MessageHeader</span><span class=\"w\"> </span><span class=\"n\">header</span><span class=\"w\">  </span><span class=\"c1\"># Message header</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">stream_id</span><span class=\"w\">  </span><span class=\"c1\"># Audio stream ID (1: onboard mic, 2: external mic; regardless of which mic is active, audio is always published with stream_id=1 and saved under the fixed stream_1/ subdirectory)</span>\n<span class=\"n\">AudioVadStateType</span><span class=\"w\"> </span><span class=\"n\">audio_vad_state</span><span class=\"w\">  </span><span class=\"c1\"># VAD state (0: no speech, 1: speech start, 2: in speech, 3: speech end)</span>\n<span class=\"n\">uint8</span><span class=\"o\">[]</span><span class=\"w\"> </span><span class=\"n\">audio_data</span><span class=\"w\">  </span><span class=\"c1\"># Audio data (PCM, 16 kHz / 16 bit / 1 ch)</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"#def-rossrv-setvolume\"]": "<ul id=\"def-rossrv-setvolume\">\n<li><p><code class=\"docutils literal notranslate\"><span class=\"pre\">SetVolume</span></code> ros2-srv @ /hal/audio/srv/SetVolume.srv</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Set Volume</span>\n<span class=\"c1\"># Service: /aimdk_5Fmsgs/srv/SetVolume</span>\n\n<span class=\"c1\"># Request</span>\n<span class=\"n\">CommonRequest</span><span class=\"w\"> </span><span class=\"n\">request</span><span class=\"w\">            </span><span class=\"c1\"># Request header</span>\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">audio_volume</span><span class=\"w\">              </span><span class=\"c1\"># Target volume (0\u2013100)</span>\n\n<span class=\"o\">---</span>\n\n<span class=\"c1\"># Response</span>\n<span class=\"n\">CommonResponse</span><span class=\"w\"> </span><span class=\"n\">reponse</span><span class=\"w\">           </span><span class=\"c1\"># Response header</span>\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">audio_volume</span><span class=\"w\">              </span><span class=\"c1\"># Current volume (0\u2013100)</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"../../example/Python.html#py-set-mic-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.23 </span>Switch Microphone Source<a class=\"headerlink\" href=\"#py-set-mic-source\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Usage</strong></p>", "a[href=\"#def-rosmsg-focusrequester\"]": "<ul id=\"def-rosmsg-focusrequester\">\n<li><p>FocusRequester ros2-msg @ hal/audio/msg/FocusRequester.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Playback source identifier</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">priority</span><span class=\"w\"> </span><span class=\"c1\"># Priority (1\u201310, default 6)</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">priority_weight</span><span class=\"w\"> </span><span class=\"c1\"># Weight (optional); breaks ties within same priority level</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"../../example/Cpp.html#cpp-get-mic-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.29 </span>Get Current Microphone<a class=\"headerlink\" href=\"#cpp-get-mic-source\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#def-rossrv-abandonaudiofocus\"]": "<ul id=\"def-rossrv-abandonaudiofocus\">\n<li><p>AbandonAudioFocus ros2-srv @ hal/audio/srv/AbandonAudioFocus.srv</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Release audio playback focus</span>\n<span class=\"c1\"># Service: /aimdk_5Fmsgs/srv/AbandonAudioFocus</span>\n\n<span class=\"c1\"># Request</span>\n<span class=\"n\">CommonRequest</span><span class=\"w\"> </span><span class=\"n\">request</span><span class=\"w\"> </span><span class=\"c1\"># Request header</span>\n\n<span class=\"n\">FocusRequester</span><span class=\"w\"> </span><span class=\"n\">focus_requester</span><span class=\"w\"> </span><span class=\"c1\"># Focus request info</span>\n\n<span class=\"o\">---</span>\n\n<span class=\"c1\"># Response</span>\n<span class=\"n\">CommonResponse</span><span class=\"w\"> </span><span class=\"n\">reponse</span><span class=\"w\"> </span><span class=\"c1\"># Response header</span>\n\n<span class=\"n\">FocusResponse</span><span class=\"w\"> </span><span class=\"n\">focus_response</span><span class=\"w\"> </span><span class=\"c1\"># Request result</span>\n</pre></div>\n</div>\n<ul class=\"simple\">\n<li><p>FocusRequester and FocusResponse are defined as above <a class=\"reference internal\" href=\"#def-rosmsg-focusrequester\"><span class=\"std std-ref\">&gt;&gt;</span></a></p></li>\n</ul>\n</li>\n</ul>", "a[href=\"../../example/Cpp.html#cpp-mic-receiver\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.20 </span>Microphone Audio Reception<a class=\"headerlink\" href=\"#cpp-mic-receiver\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses mic_receiver</strong>, subscribing to the <code class=\"docutils literal notranslate\"><span class=\"pre\">/agent/process_audio_output</span></code> topic to receive the robot\u2019s noise-reduced audio stream. It supports both internal and external microphone audio streams, and automatically saves complete speech segments as PCM files based on VAD (Voice Activity Detection) states.</p><p><strong>Features:</strong></p>", "a[href=\"#def-rosmsg-playstatechange\"]": "<ul id=\"def-rosmsg-playstatechange\">\n<li><p>PlayStateChange ros2-msg @ hal/audio/msg/PlayStateChange.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Audio playback state events</span>\n<span class=\"c1\"># Topic: /aima/hal/audio/play_state</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Playback source identifier</span>\n\n<span class=\"n\">PlayStateType</span><span class=\"w\"> </span><span class=\"n\">state</span><span class=\"w\"> </span><span class=\"c1\"># Playback state</span>\n</pre></div>\n</div>\n<ul>\n<li><p>PlayStateType ros2-msg @ hal/audio/msg/PlayStateType.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">uint8</span><span class=\"w\"> </span><span class=\"n\">value</span><span class=\"w\">   </span><span class=\"c1\"># Playback state (0: off, 1: playing, 2: stopped)</span>\n</pre></div>\n</div>\n</li>\n</ul>\n</li>\n</ul>", "a[href=\"#def-rosmsg-audioplayback\"]": "<ul id=\"def-rosmsg-audioplayback\">\n<li><p>AudioPlayback ros2-msg @ hal/audio/msg/AudioPlayback.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Audio stream playback</span>\n<span class=\"c1\"># Topic: /aima/hal/audio/playback</span>\n\n<span class=\"n\">builtin_interfaces</span><span class=\"o\">/</span><span class=\"n\">Time</span><span class=\"w\"> </span><span class=\"n\">stamps</span><span class=\"w\"> </span><span class=\"c1\"># Timestamp</span>\n\n<span class=\"n\">AudioInfo</span><span class=\"w\"> </span><span class=\"n\">info</span><span class=\"w\"> </span><span class=\"c1\"># Audio format</span>\n\n<span class=\"n\">AudioData</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"w\"> </span><span class=\"c1\"># Audio data</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Playback source identifier</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">token_id</span><span class=\"w\"> </span><span class=\"c1\"># (Optional) changing token_id clears the playback buffer (used to interrupt current playback)</span>\n</pre></div>\n</div>\n<ul id=\"def-rosmsg-audioinfo\">\n<li><p>AudioInfo ros2-msg @ hal/audio/msg/AudioInfo.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">uint8</span><span class=\"w\"> </span><span class=\"n\">channels</span><span class=\"w\"> </span><span class=\"c1\"># Number of channels</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">sample_rate</span><span class=\"w\"> </span><span class=\"c1\"># Sample rate [Hz], currently only 16000</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">size</span><span class=\"w\"> </span><span class=\"c1\"># (not used) write size [byte]</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">sample_format</span><span class=\"w\"> </span><span class=\"c1\"># Audio format, currently only S16LE</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">coding_format</span><span class=\"w\"> </span><span class=\"c1\"># Audio coding format, currently only pcm</span>\n</pre></div>\n</div>\n</li>\n</ul>\n<ul id=\"def-rosmsg-audiodata\">\n<li><p>AudioData ros2-msg @ hal/audio/msg/AudioData.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">uint8</span><span class=\"o\">[]</span><span class=\"w\"> </span><span class=\"n\">data</span>\n</pre></div>\n</div>\n</li>\n</ul>\n</li>\n</ul>", "a[href=\"#def-rosmsg-focusresponse\"]": "<ul id=\"def-rosmsg-focusresponse\">\n<li><p>FocusResponse ros2-msg @ hal/audio/msg/FocusResponse.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Audio focus change events</span>\n<span class=\"c1\"># Topic: /aima/hal/audio/focus_response</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Playback source identifier</span>\n\n<span class=\"n\">bool</span><span class=\"w\"> </span><span class=\"n\">focus_gain</span><span class=\"w\"> </span><span class=\"c1\"># Focus grant result</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"../../example/Cpp.html#cpp-set-mic-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.30 </span>Switch Microphone<a class=\"headerlink\" href=\"#cpp-set-mic-source\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Usage Instructions</strong></p>", "a[href=\"../../faq/temp_works.html#agent-only-voice\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">8.1 </span>Disable the Built-in Interaction System and Use Your Own Voice System<a class=\"headerlink\" href=\"#agent-only-voice\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>By default, when the robot is powered on, it automatically enters natural voice interaction mode, and the interaction module occupies the audio input/output streams.</strong> If you need to integrate your own voice system and access the audio streams, you can temporarily disable the built-in interaction module using the steps below. <strong>Future versions will support one-click switching to secondary-development interaction mode to further simplify custom voice system integration.</strong></p>", "a[href=\"#id8\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Audio File Playback Service<a class=\"headerlink\" href=\"#id8\" title=\"Link to this heading\">\uf0c1</a></h2><p>Call the <code class=\"docutils literal notranslate\"><span class=\"pre\">PlayAudioFile</span></code> service with the audio file path (<code class=\"docutils literal notranslate\"><span class=\"pre\">file_path</span></code> = parent directory, <code class=\"docutils literal notranslate\"><span class=\"pre\">file_name</span></code> = filename) and priority to trigger playback. A response where <code class=\"docutils literal notranslate\"><span class=\"pre\">reponse.status.value</span> <span class=\"pre\">==</span> <span class=\"pre\">1</span></code> indicates success. See examples: <a class=\"reference internal\" href=\"../../example/Cpp.html#cpp-play-audio\"><span class=\"std std-ref\">C++</span></a> / <a class=\"reference internal\" href=\"../../example/Python.html#py-play-audio\"><span class=\"std std-ref\">Python</span></a>.</p>", "a[href=\"#def-rosmsg-audioinfo\"]": "<ul id=\"def-rosmsg-audioinfo\">\n<li><p>AudioInfo ros2-msg @ hal/audio/msg/AudioInfo.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"n\">uint8</span><span class=\"w\"> </span><span class=\"n\">channels</span><span class=\"w\"> </span><span class=\"c1\"># Number of channels</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">sample_rate</span><span class=\"w\"> </span><span class=\"c1\"># Sample rate [Hz], currently only 16000</span>\n\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">size</span><span class=\"w\"> </span><span class=\"c1\"># (not used) write size [byte]</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">sample_format</span><span class=\"w\"> </span><span class=\"c1\"># Audio format, currently only S16LE</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">coding_format</span><span class=\"w\"> </span><span class=\"c1\"># Audio coding format, currently only pcm</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"#def-rossrv-setmute\"]": "<ul id=\"def-rossrv-setmute\">\n<li><p><code class=\"docutils literal notranslate\"><span class=\"pre\">SetMute</span></code> ros2-srv @ /hal/audio/srv/SetMute.srv</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Set Mute</span>\n<span class=\"c1\"># Service: /aimdk_5Fmsgs/srv/SetMute</span>\n\n<span class=\"c1\"># Request</span>\n<span class=\"n\">CommonRequest</span><span class=\"w\"> </span><span class=\"n\">request</span><span class=\"w\">            </span><span class=\"c1\"># Request header</span>\n<span class=\"n\">bool</span><span class=\"w\"> </span><span class=\"n\">is_mute</span><span class=\"w\">                     </span><span class=\"c1\"># Target mute state</span>\n\n<span class=\"o\">---</span>\n\n<span class=\"c1\"># Response</span>\n<span class=\"n\">CommonResponse</span><span class=\"w\"> </span><span class=\"n\">reponse</span><span class=\"w\">           </span><span class=\"c1\"># Response header</span>\n<span class=\"n\">bool</span><span class=\"w\"> </span><span class=\"n\">is_mute</span><span class=\"w\">                     </span><span class=\"c1\"># Current mute state</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"../../example/Cpp.html#cpp-play-audio-stream\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.22 </span>Raw Audio Stream Playback<a class=\"headerlink\" href=\"#cpp-play-audio-stream\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses play_audio_stream</strong>, which first requests audio focus then publishes a PCM file at real-time rate to the <code class=\"docutils literal notranslate\"><span class=\"pre\">/aima/hal/audio/playback</span></code> topic; it exits automatically when audio focus is taken away.</p>", "a[href=\"../../example/Python.html#py-mic-raw-receiver\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.21 </span>Raw Microphone Audio Stream Receiver<a class=\"headerlink\" href=\"#py-mic-raw-receiver\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Usage:</strong></p>", "a[href=\"../../example/Cpp.html#cpp-play-audio\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.18 </span>Audio File Playback<a class=\"headerlink\" href=\"#cpp-play-audio\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses play_audio</strong>, enabling playback of specified audio files, supporting WAV (PCM-encoded) and RAW PCM formats. Other formats such as MP3 are not supported.</p><p><strong>Features:</strong></p>", "a[href=\"../../example/Python.html#py-play-audio\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.18 </span>Audio File Playback<a class=\"headerlink\" href=\"#py-play-audio\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses play_audio</strong>, enabling playback of specified audio files, supporting WAV (PCM-encoded) and RAW PCM formats. Other formats such as MP3 are not supported.</p><p><strong>Features:</strong></p>", "a[href=\"#id7\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Speech Synthesis Services<a class=\"headerlink\" href=\"#id7\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">5.2.1 </span>Voice Control<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">\uf0c1</a></h1><p><strong>The voice control interface provides a complete set of voice interaction capabilities, including speech synthesis, speech recognition, audio noise reduction, audio playback, and volume control.</strong></p>", "a[href=\"#def-rosmsg-audiocapture\"]": "<ul id=\"def-rosmsg-audiocapture\">\n<li><p><code class=\"docutils literal notranslate\"><span class=\"pre\">AudioCapture</span></code> ros2-msg @ hal/audio/msg/AudioCapture.msg</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Raw audio capture</span>\n<span class=\"c1\"># Topic: /aima/hal/audio/capture</span>\n\n<span class=\"n\">builtin_interfaces</span><span class=\"o\">/</span><span class=\"n\">Time</span><span class=\"w\"> </span><span class=\"n\">stamps</span>\n\n<span class=\"n\">uint8</span><span class=\"w\"> </span><span class=\"n\">mic_channels</span><span class=\"w\"> </span><span class=\"c1\"># Number of microphone channels</span>\n\n<span class=\"n\">uint8</span><span class=\"w\"> </span><span class=\"n\">ref_channels</span><span class=\"w\"> </span><span class=\"c1\"># Number of reference (echo-cancellation) channels</span>\n\n<span class=\"n\">AudioInfo</span><span class=\"w\"> </span><span class=\"n\">info</span><span class=\"w\"> </span><span class=\"c1\"># Audio format</span>\n\n<span class=\"n\">AudioData</span><span class=\"w\"> </span><span class=\"n\">data</span><span class=\"w\"> </span><span class=\"c1\"># Audio data</span>\n\n<span class=\"n\">string</span><span class=\"w\"> </span><span class=\"n\">pkg_name</span><span class=\"w\"> </span><span class=\"c1\"># Audio source</span>\n</pre></div>\n</div>\n<p>AudioInfo definition <a class=\"reference internal\" href=\"#def-rosmsg-audioinfo\"><span class=\"std std-ref\">&gt;&gt;</span></a>  AudioData definition <a class=\"reference internal\" href=\"#def-rosmsg-audiodata\"><span class=\"std std-ref\">&gt;&gt;</span></a></p>\n</li>\n</ul>", "a[href=\"#def-rossrv-getvolume\"]": "<ul id=\"def-rossrv-getvolume\">\n<li><p><code class=\"docutils literal notranslate\"><span class=\"pre\">GetVolume</span></code> ros2-srv @ /hal/audio/srv/GetVolume.srv</p>\n<div class=\"highlight-perl notranslate\"><div class=\"highlight\"><pre><span></span><span class=\"c1\"># Get Volume</span>\n<span class=\"c1\"># Service: /aimdk_5Fmsgs/srv/GetVolume</span>\n\n<span class=\"c1\"># Request</span>\n<span class=\"n\">CommonRequest</span><span class=\"w\"> </span><span class=\"n\">request</span><span class=\"w\">            </span><span class=\"c1\"># Request header</span>\n\n<span class=\"o\">---</span>\n\n<span class=\"c1\"># Response</span>\n<span class=\"n\">CommonResponse</span><span class=\"w\"> </span><span class=\"n\">reponse</span><span class=\"w\">           </span><span class=\"c1\"># Response header</span>\n<span class=\"n\">uint32</span><span class=\"w\"> </span><span class=\"n\">audio_volume</span><span class=\"w\">              </span><span class=\"c1\"># Current volume (0\u2013100)</span>\n</pre></div>\n</div>\n</li>\n</ul>", "a[href=\"../../example/Python.html#py-play-tts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.19 </span>TTS (Text-to-Speech)<a class=\"headerlink\" href=\"#py-play-tts\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses play_tts</strong>, which enables the robot to speak the provided text through the node. Users can input different text according to various scenarios.</p><p><strong>Features:</strong></p>", "a[href=\"#id11\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Safety Notes<a class=\"headerlink\" href=\"#id11\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"../../example/Python.html#py-play-audio-stream\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.24 </span>Raw Audio Stream Playback<a class=\"headerlink\" href=\"#py-play-audio-stream\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>Usage</strong></p>", "a[href=\"../../example/Cpp.html#cpp-play-tts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.2.19 </span>TTS (Text-to-Speech)<a class=\"headerlink\" href=\"#cpp-play-tts\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses play_tts</strong>, enabling the robot to speak the provided text. Users can input any text depending on the scenario.</p><p><strong>Features:</strong></p>", "a[href=\"#id4\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Audio Playback<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"#id3\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Audio Processing<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"#tts\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Text-to-Speech (TTS)<a class=\"headerlink\" href=\"#tts\" title=\"Link to this heading\">\uf0c1</a></h3>", "a[href=\"#id9\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Microphone Control Services<a class=\"headerlink\" href=\"#id9\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"../../example/Python.html#py-mic-receiver\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">6.1.20 </span>Microphone data reception<a class=\"headerlink\" href=\"#py-mic-receiver\" title=\"Link to this heading\">\uf0c1</a></h2><p><strong>This example uses mic_receiver</strong>, which subscribes to the <code class=\"docutils literal notranslate\"><span class=\"pre\">/agent/process_audio_output</span></code> topic to receive noise-reduced audio data from the robot, supporting both internal and external microphone audio streams, and automatically saving complete speech segments as PCM files based on VAD (Voice Activity Detection) status.</p><p><strong>Features:</strong></p>", "a[href=\"#mic-receiver-vad\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">MIC Audio Stream Capture Topic<a class=\"headerlink\" href=\"#mic-receiver-vad\" title=\"Link to this heading\">\uf0c1</a></h2><p>Supports receiving real-time VAD (Voice Activity Detection) events on denoised audio and the corresponding audio stream, as well as raw audio stream capture.</p>", "a[href=\"#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Volume Control Services<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">\uf0c1</a></h2>", "a[href=\"#id5\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Volume Control<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">\uf0c1</a></h3>"}
